//! The `@reuse` table (`almide_lang::reuse::REUSE`) is generated by a text
//! scan of `stdlib/*.almd` (crates/almide-types/buildscript/reuse.rs). This
//! test reads the same declarations through the real parser and requires the
//! two to agree, so the scan can never drift from what the parser sees: every
//! `@reuse(p)` fn of a bundled module is one row, with its parameter index,
//! arity, intrinsic and `@consume` status, and no row names anything else.
use std::collections::BTreeSet;

use almide_lang::ast::{AttrValue, Decl};

fn arg_names(a: &almide_lang::ast::Attribute) -> Vec<String> {
    a.args
        .iter()
        .filter_map(|x| match &x.value {
            AttrValue::Ident { name } => Some(name.to_string()),
            AttrValue::String { value } => Some(value.clone()),
            _ => None,
        })
        .collect()
}

#[test]
fn the_reuse_table_is_exactly_the_parsed_reuse_declarations() {
    let mut parsed = BTreeSet::new();
    for &module in almide_lang::stdlib_info::BUNDLED_MODULES {
        let Some(source) = almide_lang::stdlib_info::bundled_source(module) else {
            continue;
        };
        let ast =
            almide_lang::parse_cached(source).unwrap_or_else(|| panic!("stdlib {module} parses"));
        for decl in &ast.decls {
            let Decl::Fn {
                name,
                params,
                attrs,
                ..
            } = decl
            else {
                continue;
            };
            let Some(reuse) = attrs.iter().find(|a| a.name.as_str() == "reuse") else {
                continue;
            };
            let [p] = &arg_names(reuse)[..] else {
                panic!("{module}.{name}: @reuse takes one parameter")
            };
            let param = params
                .iter()
                .position(|q| q.name.as_str() == p)
                .expect("@reuse names a parameter");
            let intrinsic = attrs
                .iter()
                .find(|a| a.name.as_str() == "intrinsic")
                .and_then(|a| arg_names(a).into_iter().next())
                .expect("@reuse fn has an @intrinsic");
            let consumes = attrs
                .iter()
                .any(|a| a.name.as_str() == "consume" && arg_names(a).contains(p));
            parsed.insert((
                module.to_string(),
                name.to_string(),
                param,
                params.len(),
                intrinsic,
                consumes,
            ));
        }
    }
    let table: BTreeSet<_> = almide_lang::reuse::REUSE
        .iter()
        .map(|r| {
            (
                r.module.to_string(),
                r.func.to_string(),
                r.param,
                r.arity,
                r.intrinsic.to_string(),
                r.owned_twin.is_none(),
            )
        })
        .collect();
    assert!(!parsed.is_empty(), "no @reuse declaration parsed");
    assert_eq!(
        table, parsed,
        "the generated @reuse table disagrees with the parsed declarations — rebuild almide-types"
    );
}

#[test]
fn a_native_twin_reuses_the_first_argument() {
    // BorrowLowering / CloneInsertion move `args[0]` into the twin
    // (owned_source.rs); a twin for any other position would be misapplied.
    for r in almide_lang::reuse::REUSE
        .iter()
        .filter(|r| r.owned_twin.is_some())
    {
        assert_eq!(
            r.param, 0,
            "{}.{}: the native owned-twin path moves the first argument only",
            r.module, r.func
        );
    }
}
